    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY elegible (artículo adicionado): edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CON_OLA3.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA3')
  WHERE ingest_batch = 'OLA3_CON_2021_01' AND id IN ('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:43', 'OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:43-A', 'OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:43-B');
