    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'DEROGADO', 'revision_pendiente', false, 'motivo_rol', 'DEROGADO por D.262-2000 según la edición CEDIJ; cotejo con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_CON_OLA3.md (D1–D8)', 'rol', 'CONTEXT', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA3')
  WHERE ingest_batch = 'OLA3_CON_2021_01' AND id IN ('OLA3_CON_2021_01:CONSTITUCION_REPUBLICA:377');
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND revision_pendiente = false AND metadata->>'estado_v' = 'V5';
  IF n <> 381 THEN RAISE EXCEPTION 'postcondición visibles V5 = % (esperado 381)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND es_norma_vigente = true AND NOT (metadata ? 'rol');
  IF n <> 378 THEN RAISE EXCEPTION 'postcondición PRIMARY vigentes = % (esperado 378)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND es_norma_vigente = true AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT vigentes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 3 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 3)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND es_norma_vigente IS NULL AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT pendientes = % (esperado 0)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' AND es_norma_vigente = false AND NOT (metadata ? 'rol');
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición derogados PRIMARY (prohibido) = % (esperado 0)', n; END IF;
  UPDATE public.biblioteca_vectores b SET revision_pendiente = true,
    metadata = b.metadata || jsonb_build_object('sustituido_por_lote', 'OLA3_CON_2021_01', 'sustituido_fecha', '2026-11-24', 'revision_pendiente_motivo', 'Sustituida por HN:CONSTITUCION_REPUBLICA V5 (OLA3); oculta, no borrada')
  WHERE b.id LIKE 'mayalex_normativos:constitucion_1982_a%' AND b.revision_pendiente = false;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 378 THEN RAISE EXCEPTION 'legacy ocultadas: % (esperadas 378)', n; END IF;
END $do$;
COMMIT;
SELECT count(*) AS filas, count(*) FILTER (WHERE revision_pendiente = false) AS visibles, metadata->>'estado_v' AS estado_v,
  count(*) FILTER (WHERE es_norma_vigente = true AND NOT (metadata ? 'rol')) AS primary_vigentes,
  count(*) FILTER (WHERE metadata->>'rol' = 'CONTEXT') AS context,
  count(*) FILTER (WHERE es_norma_vigente = false) AS derogados,
  count(*) FILTER (WHERE embedding IS NOT NULL) AS con_embedding,
  count(*) FILTER (WHERE encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido) AS sha_ok
FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA3_CON_2021_01' GROUP BY metadata->>'estado_v';
